CREATE TABLE CD_COLETA (id VARCHAR2(36) PRIMARY KEY, solicitacao_id VARCHAR2(36) NOT NULL UNIQUE, correlation_id VARCHAR2(36) NOT NULL, dados CLOB NOT NULL, status VARCHAR2(20) DEFAULT 'CONFIRMADA' NOT NULL CHECK(status IN ('CONFIRMADA','EXECUTADA','TRIADA','DESTINADA')), criado_em TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL, atualizado_em TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL)
;
CREATE TABLE CD_INBOX (message_id VARCHAR2(36) PRIMARY KEY, processada_em TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL)
;
CREATE TABLE CD_OUTBOX (message_id VARCHAR2(36) PRIMARY KEY, correlation_id VARCHAR2(36) NOT NULL, tipo_evento VARCHAR2(80) NOT NULL, routing_key VARCHAR2(100) NOT NULL, payload CLOB NOT NULL, status VARCHAR2(15) DEFAULT 'PENDENTE' NOT NULL CHECK(status IN ('PENDENTE','PROCESSANDO','PUBLICADO')), criado_em TIMESTAMP DEFAULT SYS_EXTRACT_UTC(SYSTIMESTAMP) NOT NULL, reservado_ate TIMESTAMP, token_reserva VARCHAR2(36), publicado_em TIMESTAMP)
;
CREATE TABLE CD_COMPROVANTE (id VARCHAR2(64) PRIMARY KEY, coleta_id VARCHAR2(36) NOT NULL REFERENCES CD_COLETA(id), objeto VARCHAR2(300) NOT NULL, nome VARCHAR2(255) NOT NULL, mime VARCHAR2(100) NOT NULL, tamanho NUMBER NOT NULL)
;
CREATE INDEX CD_OUTBOX_IDX ON CD_OUTBOX(status, criado_em)
